<script setup lang="ts">
import {requestKey} from './requestKey';
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import AccountingDocument from './AccountingDocument.vue';
import AdminDialog from '../../AdminDialog.vue';
const props=defineProps<{section:string;company:number;book:any;accounts:any[];canManage:boolean;canAdmin:boolean;csrf?:string}>();
const emit=defineEmits(['notice','setup']);
const today=new Date().toLocaleDateString('en-CA'),page=ref(1),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),query=ref(''),state=ref(''),data=ref<any>(null),editor=ref<any>(null),dialog=ref(''),parties=ref<any[]>([]),partyQuery=ref(''),contactLoading=ref(false),payment=ref<any>({}),reversal=ref<any>({});let generation=0;
const contact=computed(()=>['customers','suppliers'].includes(props.section));
const sale=computed(()=>props.section==='sales');
const title=computed(()=>({customers:'Customers',suppliers:'Suppliers',sales:'Sales invoices',purchases:'Purchase invoices'} as Record<string,string>)[props.section]);
const ledgers=computed(()=>props.accounts.filter(a=>a.active&&!a.is_group));
const controls=computed(()=>ledgers.value.filter(a=>a.account_type===(sale.value?'Receivable':'Payable')));
const lineAccounts=computed(()=>ledgers.value.filter(a=>(sale.value?a.root_type==='Income':['Expense','Asset'].includes(a.root_type))&&!['Receivable','Payable','Cash','Bank'].includes(a.account_type)));
const taxAccounts=computed(()=>ledgers.value.filter(a=>a.root_type===(sale.value?'Liability':'Asset')&&!['Receivable','Payable','Cash','Bank'].includes(a.account_type)));
const bankAccounts=computed(()=>ledgers.value.filter(a=>a.root_type==='Asset'&&['Bank','Cash'].includes(a.account_type)));
const canEdit=computed(()=>contact.value||editor.value?.status==='draft');
const money=(v:any)=>Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
const saved=ref('');
function signature(i:any){return JSON.stringify([i.party_id,i.posting_date,i.due_date,i.control_account_id,i.tax_account_id||null,String(i.tax_percent),i.tax_label||'',i.reference||'',i.notes||'',i.lines.map((l:any)=>[l.account_id,l.description,String(l.quantity),String(l.rate)])]);}
async function api(path:string,body?:any){const r=await fetch('/accounting/api/'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const result=await r.json();if(!r.ok)throw Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to complete this action.');return result;}
async function load(){const g=++generation;error.value='';data.value=null;loading.value=true;try{const p=new URLSearchParams({company_id:String(props.company),page:String(page.value),kind:contact.value?(props.section==='customers'?'customer':'supplier'):(sale.value?'sale':'purchase')});if(contact.value)p.set('search',query.value);else if(state.value)p.set('status',state.value);const result=await api((contact.value?'parties':'invoices')+'?'+p);if(g===generation)data.value=result;}catch(e){if(g===generation)error.value=(e as Error).message;}finally{if(g===generation)loading.value=false;}}
watch(()=>[props.section,props.company],()=>{page.value=1;query.value='';state.value='';dialog.value='';editor.value=null;void load();},{immediate:true});
onBeforeUnmount(()=>generation++);
async function findParties(){contactLoading.value=true;try{const result=await api('parties?'+new URLSearchParams({company_id:String(props.company),kind:sale.value?'customer':'supplier',search:partyQuery.value}));parties.value=result.data.filter((p:any)=>p.active);}catch(e){formError.value=(e as Error).message;}finally{contactLoading.value=false;}}
async function create(){formError.value='';if(contact.value){editor.value={company_id:props.company,kind:props.section==='customers'?'customer':'supplier',name:'',email:'',phone:'',address:'',tax_number:'',active:true};}else{editor.value={company_id:props.company,request_key:requestKey(),kind:sale.value?'sale':'purchase',party_id:'',posting_date:today,due_date:today,control_account_id:controls.value[0]?.id||'',tax_percent:'0.00',tax_label:'',tax_account_id:null,reference:'',notes:'',status:'draft',lines:[{description:'',quantity:'1.00',rate:'0.00',account_id:''}]};partyQuery.value='';parties.value=[];dialog.value='edit';void findParties();return;}dialog.value='edit';}
async function open(row:any){formError.value='';try{editor.value=contact.value?{...row}:(await api('invoices?company_id='+props.company+'&id='+row.id)).invoice;if(!contact.value){saved.value=signature(editor.value);parties.value=[{id:editor.value.party_id,name:editor.value.party_name}];}dialog.value='edit';}catch(e){error.value=(e as Error).message;}}
async function run(action:string){if(busy.value)return;if(action==='post'&&signature(editor.value)!==saved.value){formError.value='Save all draft changes before posting.';return;}busy.value=true;formError.value='';try{let result;if(action==='save')result=await api(contact.value?'parties':'invoices',editor.value);else result=await api('invoices/'+editor.value.id+'/'+(action==='payment'?'payments':action),action==='post'?{company_id:props.company,version:editor.value.version}:action==='payment'?{...payment.value,company_id:props.company}:{...reversal.value,company_id:props.company});emit('notice',result.message);if(result.invoice){editor.value=result.invoice;saved.value=signature(editor.value);dialog.value='edit';}else dialog.value='';await load();}catch(e){formError.value=(e as Error).message;}finally{busy.value=false;}}
function startPayment(){payment.value={request_key:requestKey(),posting_date:today,amount:editor.value.outstanding,bank_account_id:bankAccounts.value[0]?.id||'',reference:''};formError.value='';dialog.value='payment';}
function startReversal(p?:any){reversal.value={version:p?.version||editor.value.version,payment_id:p?.id||null,posting_date:today,reason:''};dialog.value='reverse';formError.value='';}
function review(){if(signature(editor.value)!==saved.value){formError.value='Save all draft changes before reviewing posting.';return;}dialog.value='post';}
</script>
<template><section :class="{'ac-document-open':!contact&&(dialog==='edit'||dialog==='post')}"><div class="ac-section-heading"><div><h2>{{title}}</h2><p class="muted">{{contact?'Manage company-specific contacts and tax references.':'Track invoices, outstanding balances and allocated payments.'}}</p></div><button v-if="canManage" class="button primary" :disabled="busy" @click="create">+ {{contact?'Create contact':'Create invoice'}}</button></div><p v-if="error" role="alert" class="notice admin-error">{{error}}</p><p v-if="!contact&&!book" class="ac-help">Set up Company books before creating invoices.</p><form class="ac-filters" @submit.prevent="page=1;load()"><label v-if="contact" class="ac-search">Find contact<input v-model="query" type="search" placeholder="Search by name"></label><label v-else>Status<select v-model="state"><option value="">All statuses</option><option value="draft">Draft</option><option value="posted">Posted</option><option value="reversed">Reversed</option></select></label><button class="button" :disabled="loading">Apply filters</button></form><p v-if="loading" role="status">Loading records...</p><div v-else-if="data" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr v-if="contact"><th>Name</th><th>Email / phone</th><th>Tax reference</th><th>Status</th><th>Action</th></tr><tr v-else><th>Invoice</th><th>{{sale?'Customer':'Supplier'}}</th><th>Date / Due</th><th>Status</th><th class="numeric">Total</th><th class="numeric">Outstanding</th><th>Action</th></tr></thead><tbody><tr v-for="row in data.data" :key="row.id"><template v-if="contact"><td><strong>{{row.name}}</strong></td><td>{{row.email||'-'}}<small>{{row.phone}}</small></td><td>{{row.tax_number||'-'}}</td><td>{{row.active?'Active':'Inactive'}}</td><td><button class="button" @click="open(row)">{{canManage?'Edit':'View'}}</button></td></template><template v-else><td><strong>{{row.number}}</strong><small>{{row.reference}}</small></td><td>{{row.party_name}}</td><td>{{row.posting_date}}<small>Due {{row.due_date}}</small></td><td><span class="ac-badge" :class="row.status==='posted'?'active':'inactive'">{{row.status}}</span><small v-if="row.status==='posted'">{{Number(row.outstanding)===0?'Paid':Number(row.paid)>0?'Partially paid':'Unpaid'}}</small></td><td class="numeric">{{money(row.total)}}</td><td class="numeric">{{money(row.outstanding)}}</td><td><button class="button" @click="open(row)">View invoice</button></td></template></tr><tr v-if="!data.data.length"><td colspan="8" class="ac-empty-small">No records found.</td></tr></tbody></table></div><div v-if="data" class="ac-pagination"><span>Page {{page}} of {{data.last_page}} &middot; {{data.total}} records</span><button class="button" :disabled="page<=1||loading" @click="page--;load()">Previous</button><button class="button" :disabled="page>=data.last_page||loading" @click="page++;load()">Next</button></div>
<component :is="(!contact&&(dialog==='edit'||dialog==='post'))?AccountingDocument:AdminDialog" v-if="dialog&&editor" :title="dialog==='payment'?(sale?'Receive customer payment':'Pay supplier'):dialog==='reverse'?'Reverse transaction':contact?(editor.id?'Contact details':'Create contact'):(editor.number||'Create invoice')" :busy="busy" dialog-class="ac-dialog ac-journal-dialog" @close="!busy&&(dialog='')"><p v-if="!contact&&!book" class="ac-help">Company books are not set up yet. You can prepare this form, but an Accounting Manager must set the currency and start date in Company books before it can be saved. <button type="button" class="button" @click="dialog='';emit('setup')">Open Company books</button></p><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p>
<form v-if="dialog==='payment'" @submit.prevent="run('payment')"><p>Allocate a payment to {{editor.number}}. Outstanding: <strong>{{book?.currency}} {{money(editor.outstanding)}}</strong></p><div class="ac-form-grid"><label>Payment date<input v-model="payment.posting_date" type="date" required :min="editor.posting_date" :max="today"></label><label>Amount<input v-model="payment.amount" inputmode="decimal" required></label><label>Cash or bank account<select v-model.number="payment.bank_account_id" required><option value="" disabled>Select account</option><option v-for="a in bankAccounts" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></label><label>Payment reference<input v-model="payment.reference" required maxlength="150" placeholder="Transaction or receipt reference"></label></div><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="dialog='edit'">Back</button><button class="button primary" :disabled="busy">{{busy?'Posting payment...':'Confirm and post payment'}}</button></div></form>
<form v-else-if="dialog==='reverse'" @submit.prevent="run('reverse')"><p>This posts an opposite ledger entry and retains the original record. Active payments must be reversed before the invoice.</p><label>Reversal date<input v-model="reversal.posting_date" type="date" required :max="today"></label><label>Reason<textarea v-model="reversal.reason" required minlength="5" maxlength="2000"></textarea></label><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="dialog='edit'">Back</button><button class="button primary" :disabled="busy">{{busy?'Reversing...':'Confirm reversal'}}</button></div></form>
<form v-else @submit.prevent="run('save')"><fieldset :disabled="busy||!canManage||!canEdit||dialog==='post'" class="ac-journal-fields"><div v-if="contact" class="ac-form-grid"><label>Name<input v-model="editor.name" required maxlength="150"></label><label>Email<input v-model="editor.email" type="email"></label><label>Phone<input v-model="editor.phone" maxlength="50"></label><label>NTN / tax reference<input v-model="editor.tax_number" maxlength="100"></label><label>Address<textarea v-model="editor.address" maxlength="2000"></textarea></label><label class="ac-check"><input v-model="editor.active" type="checkbox">Active contact</label></div><template v-else><p class="ac-help">{{editor.status==='draft'?'Draft invoices have no accounting effect until posted.':'This invoice has been posted; edits require a reversal.'}} Amounts in {{book?.currency}}.</p><div class="ac-form-grid"><label>{{sale?'Customer':'Supplier'}}<select v-model.number="editor.party_id" :aria-label="sale?'Customer':'Supplier'" required><option disabled value="">Select contact</option><option v-for="p in parties" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label v-if="canEdit">Find contact<div class="ac-inline-search"><input v-model="partyQuery" placeholder="Search contacts"><button type="button" class="button" :disabled="contactLoading" @click="findParties">{{contactLoading?'Finding...':'Find'}}</button></div></label><label>Posting date<input v-model="editor.posting_date" type="date" required :max="today" :min="book?.start_date"></label><label>Due date<input v-model="editor.due_date" type="date" required :min="editor.posting_date"></label><label>{{sale?'Receivable':'Payable'}} account<select v-model.number="editor.control_account_id" required><option v-if="!controls.some(a=>a.id===editor.control_account_id)&&editor.control_account_id" :value="editor.control_account_id">Existing control account</option><option v-for="a in controls" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></label><label>Reference<input v-model="editor.reference" maxlength="150"></label></div><div class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Description</th><th>{{sale?'Income':'Expense / asset'}} account</th><th>Quantity</th><th>Unit rate</th><th></th></tr></thead><tbody><tr v-for="(line,index) in editor.lines" :key="index"><td><input v-model="line.description" required maxlength="250" :aria-label="'Description line '+(index+1)"></td><td><select v-model.number="line.account_id" required :aria-label="'Account line '+(index+1)"><option disabled value="">Select account</option><option v-if="!lineAccounts.some(a=>a.id===line.account_id)&&line.account_id" :value="line.account_id">Existing account #{{line.account_id}}</option><option v-for="a in lineAccounts" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></td><td><input v-model="line.quantity" inputmode="decimal" required :aria-label="'Quantity line '+(index+1)"></td><td><input v-model="line.rate" inputmode="decimal" required :aria-label="'Rate line '+(index+1)"></td><td><button type="button" class="button" :disabled="editor.lines.length<=1" :aria-label="'Remove line '+(index+1)" @click="editor.lines.splice(index,1)">&times;</button></td></tr></tbody></table></div><button v-if="canEdit&&canManage" type="button" class="button" :disabled="editor.lines.length>=100" @click="editor.lines.push({description:'',quantity:'1.00',rate:'0.00',account_id:''})">+ Add line</button><div class="ac-form-grid" style="margin-top:20px"><label>Tax percentage<input v-model="editor.tax_percent" inputmode="decimal" required><small>Use the rate approved for this transaction. No statutory rate is assumed.</small></label><label v-if="Number(editor.tax_percent)>0">Tax name / jurisdiction<input v-model="editor.tax_label" maxlength="150" required></label><label v-if="Number(editor.tax_percent)>0">{{sale?'Output tax liability':'Input tax asset'}} account<select v-model.number="editor.tax_account_id" required><option disabled :value="null">Select tax account</option><option v-for="a in taxAccounts" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></label><label>Notes<textarea v-model="editor.notes" maxlength="2000" rows="2"></textarea></label></div></template></fieldset>
<a v-if="!contact&&editor.id" class="button" :href="'/accounting/invoices/'+editor.id+'/print'" target="_blank" rel="noopener">Print / save PDF</a><div v-if="!contact&&editor.id" class="ac-journal-totals"><span>Net <strong>{{money(editor.net)}}</strong></span><span>Tax <strong>{{money(editor.tax)}}</strong></span><span>Total <strong>{{book?.currency}} {{money(editor.total)}}</strong></span><span>Outstanding <strong>{{money(editor.outstanding)}}</strong></span></div>
<div v-if="!contact&&editor.payments?.length" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Payment</th><th>Date</th><th>Reference</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in editor.payments" :key="p.id"><td>{{p.number}}</td><td>{{p.posting_date}}</td><td>{{p.reference}}</td><td>{{money(p.amount)}}</td><td>{{p.status}}</td><td><button v-if="canAdmin&&p.status==='posted'" class="button ac-danger" type="button" @click="startReversal(p)">Reverse payment</button></td></tr></tbody></table></div>
<div v-if="dialog==='post'" class="ac-post-confirm"><p>Post this saved invoice and its receivable / payable to the General Ledger?</p><button type="button" class="button primary" :disabled="busy" @click="run('post')">{{busy?'Posting...':'Confirm posting invoice'}}</button><button type="button" class="button" :disabled="busy" @click="dialog='edit'">Back</button></div>
<div v-else class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="dialog=''">Close</button><button v-if="canManage&&canEdit" class="button primary" :disabled="busy||(!contact&&!book)">{{busy?'Saving...':contact?'Save contact':'Save invoice draft'}}</button><button v-if="!contact&&editor.id&&editor.status==='draft'&&canManage" type="button" class="button" :disabled="busy" @click="review">Review posting</button><button v-if="!contact&&editor.status==='posted'&&Number(editor.outstanding)>0&&canManage" type="button" class="button primary" :disabled="busy" @click="startPayment">{{sale?'Receive payment':'Make payment'}}</button><button v-if="!contact&&editor.status==='posted'&&canAdmin" type="button" class="button ac-danger" :disabled="busy" @click="startReversal()">Reverse invoice</button></div></form></component>
</section></template>
